// DUPLICATE DETECTION — the same charge twice, which is recoverable money.
//
// THE FAILURE MODE IS THE FALSE POSITIVE, not the miss. Flag two legitimate coffees as a double
// charge and the reader learns to ignore the report; after that it finds nothing no matter how good
// it gets. So this SCORES a pair and hands the judgement to a person, rather than pronouncing.
//
// What actually separates a duplicate from a repeat is not "same merchant, same day" — it is how
// SURPRISING the coincidence is:
//
//   - An exact cent-for-cent match on an unusual amount ($47.83 twice) is very unlikely by chance.
//   - The same round amount twice ($5.00) is a habit, not an error.
//   - At a merchant you visit constantly, a repeat is expected and means nothing.
//   - At a merchant you use rarely, a same-day repeat is worth a look.
//
// So the score is built from the coincidence being improbable, and damped by how habitual the
// merchant is. That is the difference between a feature people act on and one they mute.
import { type Money, format } from "@/features/finance/lib/money";
import { type Txn, daysBetween, merchantKey } from "@/features/finance/lib/txn";

export interface Candidate {
  readonly account: string;
  /** The merchant key both share. */
  readonly key: string;
  /** The two descriptions, as written — a person recognises the charge by these, not by the key. */
  readonly descriptions: readonly [string, string];
  readonly dates: readonly [string, string];
  readonly amount: Money;
  /** Days apart. `0` is the same day. */
  readonly apart: number;
  /** 0-1. How unlikely this pair is to be an ordinary repeat. */
  readonly score: number;
  /** Why it scored that way, in words — a score with no reason cannot be argued with, and a reader
   *  who cannot argue with it cannot trust it either. */
  readonly reasons: readonly string[];
  /** What is at stake if it IS a duplicate — the amount that would come back. */
  readonly atStake: Money;
}

export interface DuplicateOptions {
  /** How far apart two charges can be and still be considered one event. Beyond a few days a repeat
   *  is much more likely to be a genuine second purchase. */
  readonly withinDays?: number;
  /** Report only pairs scoring at least this. Default deliberately high: a short list that is right
   *  beats a long list that has to be filtered by hand. */
  readonly minScore?: number;
}

/** An amount is ROUND when it looks chosen rather than computed — whole units, or a common price. */
function isRound(minor: number): boolean {
  const a = Math.abs(minor);
  return a % 100 === 0 || a % 50 === 0;
}

/**
 * Pairs of charges that might be the same charge twice.
 *
 * Only ever compares within one account: the same amount on two different cards on one day is two
 * purchases, not a double charge, and merging that judgement would produce confident nonsense.
 */
export function findDuplicates(txns: readonly Txn[], opts: DuplicateOptions = {}): Candidate[] {
  const { withinDays = 3, minScore = 0.5 } = opts;

  // How often each merchant appears at all — the damping term. A merchant seen 40 times is a habit.
  const frequency = new Map<string, number>();
  for (const t of txns) {
    const k = merchantKey(t.description);
    if (k) frequency.set(k, (frequency.get(k) ?? 0) + 1);
  }

  const out: Candidate[] = [];
  const byAccount = new Map<string, Txn[]>();
  for (const t of txns) {
    if (t.amount.minor >= 0) continue; // an inbound pair is a refund pattern, not a double charge
    const bucket = byAccount.get(t.account);
    if (bucket) bucket.push(t);
    else byAccount.set(t.account, [t]);
  }

  for (const [account, rows] of byAccount) {
    const sorted = [...rows].sort((a, b) => a.date.localeCompare(b.date));
    for (let i = 0; i < sorted.length; i++) {
      for (let j = i + 1; j < sorted.length; j++) {
        const [a, b] = [sorted[i], sorted[j]];
        const apart = daysBetween(a.date, b.date);
        if (apart > withinDays) break; // sorted, so nothing later is closer
        if (a.amount.minor !== b.amount.minor) continue;
        const key = merchantKey(a.description);
        if (!key || key !== merchantKey(b.description)) continue;

        const reasons: string[] = [];
        // Base: an exact cent-for-cent match at one merchant, close together.
        let score = 0.5;
        reasons.push(`exact match ${format(a.amount)}, ${apart === 0 ? "same day" : `${apart} day(s) apart`}`);

        if (apart === 0) {
          score += 0.2;
          reasons.push("same day");
        }
        if (!isRound(a.amount.minor)) {
          // An unusual amount repeating exactly is the strongest signal available: a habit produces
          // round prices, a duplicated transaction reproduces whatever the total happened to be.
          score += 0.25;
          reasons.push("unusual amount — an exact repeat is unlikely by chance");
        }
        const seen = frequency.get(key) ?? 0;
        if (seen > 10) {
          // A merchant you use constantly: a repeat means nothing, and saying so is the point.
          score -= 0.35;
          reasons.push(`frequent merchant (${seen} charges) — a repeat here is expected`);
        } else if (seen <= 3) {
          score += 0.15;
          reasons.push(`rare merchant (${seen} charges)`);
        }

        const clamped = Math.max(0, Math.min(1, score));
        if (clamped < minScore) continue;
        out.push({
          account,
          key,
          descriptions: [a.description, b.description],
          dates: [a.date, b.date],
          amount: a.amount,
          apart,
          score: Math.round(clamped * 100) / 100,
          reasons,
          // What comes back if it is a duplicate: ONE of the two, not both.
          atStake: a.amount,
        });
      }
    }
  }
  // Most likely first, then biggest — a reader works down this list and stops when it stops paying.
  return out.sort((a, b) => b.score - a.score || Math.abs(b.atStake.minor) - Math.abs(a.atStake.minor));
}

