import { describe, it, expect } from "vitest";
import { fromMajor, type Money } from "@/features/finance/lib/money";
import { findDuplicates } from "@/features/finance/lib/duplicates";
import type { Txn } from "@/features/finance/lib/txn";

// SYNTHETIC FIXTURES ONLY.
const usd = (major: number): Money => fromMajor(major, "USD");
const t = (date: string, description: string, major: number, account = "card"): Txn => ({
  date,
  description,
  amount: usd(-Math.abs(major)),
  account,
});

describe("findDuplicates — what it should catch", () => {
  it("catches an exact repeat of an UNUSUAL amount on the same day", () => {
    // The strongest available signal: a habit produces round prices, a double charge reproduces
    // whatever the total happened to be.
    const rows = [t("2026-03-04", "APPLIANCE REPAIR CO", 247.83), t("2026-03-04", "APPLIANCE REPAIR CO", 247.83)];
    const [d] = findDuplicates(rows);
    expect(d).toBeDefined();
    expect(d.score).toBeGreaterThan(0.8);
    expect(d.atStake.minor).toBe(-24783);
    expect(d.reasons.join(" ")).toMatch(/unusual amount/);
  });

  it("catches one a couple of days apart, with a lower score", () => {
    const same = findDuplicates([t("2026-03-04", "PLUMBER LTD", 189.44), t("2026-03-04", "PLUMBER LTD", 189.44)]);
    const apart = findDuplicates([t("2026-03-04", "PLUMBER LTD", 189.44), t("2026-03-06", "PLUMBER LTD", 189.44)]);
    expect(apart).toHaveLength(1);
    expect(apart[0].apart).toBe(2);
    // Same day is more suspicious than two days later, and the score has to say so or it is not a
    // score, it is a label.
    expect(same[0].score).toBeGreaterThan(apart[0].score);
  });

  it("reports WHY, so the reader can disagree with it", () => {
    const [d] = findDuplicates([t("2026-03-04", "RARE VENDOR", 133.17), t("2026-03-04", "RARE VENDOR", 133.17)]);
    expect(d.reasons.length).toBeGreaterThan(1);
    expect(d.descriptions[0]).toBe("RARE VENDOR");
    expect(d.dates).toEqual(["2026-03-04", "2026-03-04"]);
  });
});

describe("findDuplicates — the false positive is the failure mode", () => {
  it("does NOT flag two coffees at a merchant you use constantly", () => {
    // Flag someone's habit as a double charge and they stop reading the report; after that it finds
    // nothing however good it gets. This is the test that protects the whole feature.
    const habit: Txn[] = [];
    for (let d = 1; d <= 20; d++) habit.push(t(`2026-03-${String(d).padStart(2, "0")}`, "COFFEE BAR", 5.0));
    habit.push(t("2026-03-20", "COFFEE BAR", 5.0)); // a second coffee that day
    const found = findDuplicates(habit);
    expect(found).toEqual([]);
  });

  it("damps a ROUND amount, which reads as a chosen price rather than a computed total", () => {
    const round = findDuplicates([t("2026-03-04", "SOME SHOP", 50.0), t("2026-03-04", "SOME SHOP", 50.0)]);
    const odd = findDuplicates([t("2026-03-04", "SOME SHOP", 51.37), t("2026-03-04", "SOME SHOP", 51.37)]);
    expect(odd[0].score).toBeGreaterThan(round[0].score);
  });

  it("ignores a pair whose amounts differ at all", () => {
    // A cent apart is two purchases, not one charge twice.
    expect(findDuplicates([t("2026-03-04", "SHOP", 20.0), t("2026-03-04", "SHOP", 20.01)])).toEqual([]);
  });

  it("ignores a pair further apart than the window", () => {
    expect(findDuplicates([t("2026-03-04", "VENDOR", 99.13), t("2026-03-20", "VENDOR", 99.13)])).toEqual([]);
  });
});

describe("findDuplicates — what it must not merge", () => {
  it("never pairs across ACCOUNTS", () => {
    // The same amount on two cards on one day is two purchases. Pairing them would be confident
    // nonsense — and the refund it suggests does not exist.
    const rows = [t("2026-03-04", "VENDOR", 77.31, "card-a"), t("2026-03-04", "VENDOR", 77.31, "card-b")];
    expect(findDuplicates(rows)).toEqual([]);
  });

  it("ignores inbound pairs — two refunds are not a double charge", () => {
    const refunds: Txn[] = [
      { date: "2026-03-04", description: "VENDOR REFUND", amount: usd(25.5), account: "card" },
      { date: "2026-03-04", description: "VENDOR REFUND", amount: usd(25.5), account: "card" },
    ];
    expect(findDuplicates(refunds)).toEqual([]);
  });
});

describe("findDuplicates — ordering", () => {
  it("puts the most likely first, then the biggest", () => {
    const rows = [
      t("2026-03-04", "RARE BIG VENDOR", 431.29),
      t("2026-03-04", "RARE BIG VENDOR", 431.29),
      t("2026-04-04", "RARE SMALL VENDOR", 61.13),
      t("2026-04-04", "RARE SMALL VENDOR", 61.13),
    ];
    const found = findDuplicates(rows);
    expect(found).toHaveLength(2);
    expect(Math.abs(found[0].atStake.minor)).toBeGreaterThan(Math.abs(found[1].atStake.minor));
  });
});
